public static class FixTransferArt19 {public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||SceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit only");const string A="Assets/ShooterSurvival/Models/Chapters/Chapters45/Ch5Toon20261004";string rec="outputs/ch5-toon-2026-10-04/recovery-before-transfer-art.unity";if(File.Exists(rec))throw new Exception("Already applied");File.Copy(SceneManager.GetActiveScene().path,rec,false);var root=GameObject.Find("Chapter45_World/DetailedMall_20261003").transform;int floors=0,paintRenderers=0;foreach(var floor in root.Find("Scenery").Cast<Transform>().Where(t=>t.name.Contains(" · ")).ToArray()){var detail=floor.Find("Toon floor detail 19");if(detail==null)continue;int f=floor.GetComponent<Chapter45SceneryGroup>().floor;var paints=detail.GetComponentsInChildren<MeshRenderer>().Where(r=>r.sharedMaterial.name=="Coral signage and floor"||r.sharedMaterial.name=="Peach floor diamonds").ToArray();if(paints.Length==0)continue;var g=new GameObject("Toon floor accents transfer visibility").transform;g.SetParent(floor.parent,false);g.localPosition=floor.localPosition;var vis=g.gameObject.AddComponent<Chapter45SceneryGroup>();vis.floor=f;vis.alwaysVisible=true;vis.hideWhileArriving=true;foreach(var r in paints){r.transform.SetParent(g,true);paintRenderers++;}floors++;}
 var baseMat=AssetDatabase.LoadAssetAtPath<Material>(A+"/Deep teal recess.mat");var metal=new Material(baseMat){name="Escalator brushed graphite"};metal.SetColor("_BaseColor",new Color(.51f,.59f,.59f,1));metal.SetColor("_ColorDim",new Color(.30f,.38f,.39f,1));AssetDatabase.CreateAsset(metal,A+"/Escalator brushed graphite.mat");var treads=root.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name=="Metal escalator tread").ToArray();int n=0;foreach(var group in treads.GroupBy(r=>r.transform.parent)){var created=new List<GameObject>();var owner=new GameObject("Toon metal escalator risers").transform;owner.SetParent(group.Key,false);foreach(var r in group){r.sharedMaterial=metal;var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name="Escalator closed metal riser";g.transform.SetParent(owner,false);g.transform.SetPositionAndRotation(r.transform.position-r.transform.forward*.245f-Vector3.up*.14f,r.transform.rotation);g.transform.localScale=new Vector3(5,.29f,.06f);Object.DestroyImmediate(g.GetComponent<Collider>());g.GetComponent<Renderer>().sharedMaterial=metal;created.Add(g);}var mesh=new Mesh();mesh.CombineMeshes(created.Select(g=>new CombineInstance{mesh=g.GetComponent<MeshFilter>().sharedMesh,transform=owner.worldToLocalMatrix*g.transform.localToWorldMatrix}).ToArray());AssetDatabase.CreateAsset(mesh,A+"/Closed-escalator-risers-"+(n++)+".asset");owner.gameObject.AddComponent<MeshFilter>().sharedMesh=mesh;var rr=owner.gameObject.AddComponent<MeshRenderer>();rr.sharedMaterial=metal;rr.shadowCastingMode=ShadowCastingMode.Off;foreach(var g in created)Object.DestroyImmediate(g);}
